function length(value: string | string[] | null): number {
  if (value === null) return 0;
  if (typeof value === "string") return value.length;
  return value.length; // здесь string[]
}
// Для различения объектов полезны точные discriminant-поля.

type User = { name: string };
function isUser(value: unknown): value is User {
  return typeof value === "object" && value !== null
    && "name" in value && typeof value.name === "string";
}
function label(value: unknown): string {
  return isUser(value) ? value.name : "не пользователь";
}

function assertString(value: unknown): asserts value is string {
  if (typeof value !== "string") throw new TypeError("Нужна строка");
}
function normalize(value: unknown): string {
  assertString(value);
  return value.trim();
}

type State = { kind: "ready"; value: string } | { kind: "error"; message: string };
function render(state: State): string {
  switch (state.kind) {
    case "ready": return state.value;
    case "error": return state.message;
    default: { const impossible: never = state; throw new Error(`Неизвестный вариант: ${impossible}`); }
  }
}

function readers(input: string | URL, items: string[]) {
  if (typeof input === 'string') input = new URL(input)
  const url = input
  return items.map((item) => url.origin + '/' + item)
}
// const url хранит проверенную ссылку независимо от дальнейшего
